export const ADVANCED_SPECIFIC_CATALOG_WORKFLOW_COUNT = Object.keys(ADVANCED_SPECIFIC_WORKFLOWS).length;
export const hasAdvancedSpecificCatalogWorkflow = (name: string): boolean => Boolean(ADVANCED_SPECIFIC_WORKFLOWS[name]);
export const advancedSpecificCatalogWorkflow = (name: string): TechniqueStepDefinition[] | undefined => ADVANCED_SPECIFIC_WORKFLOWS[name]?.map((item) => ({ ...item }));
